8	
9	/**
10	 * Responds 409 Conflict when a create request would add a second owner to an existing household
11	 * (same lastName and postcode) without declaring itself a member via {@code sharesHousehold}.
12	 */
13	public class DuplicateOwnerIdentityExceptionHandler {
14	
15	    public void handle(@Parameter DuplicateOwnerIdentityException ex,
16	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
17	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
18	                "An owner with this identity already exists");
19	        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
20	    }
21	}
