17	    /** Number of leading hex characters of the digest kept as HASH8. */
18	    private static final int HASH_LENGTH = 8;
19	
20	    private CustomerCode() {
21	    }
22	
23	    /**
24	     * The customer code for the given {@code region} and person, hashing the person's
25	     * {@code normalizedTelephone} and {@code lastName}.
26	     */
27	    public static String of(String region, String normalizedTelephone, String lastName) {
28	        return region + SEPARATOR + hash8(orEmpty(normalizedTelephone) + orEmpty(lastName));
